// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public {
        c = new SimpleSuicide();
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(uint256 amount, address owner) public {
        vm.assume(amount > 0 && amount <= address(c).balance);
        vm.assume(owner != address(0));
        vm.deal(owner, 0);
        vm.prank(owner);
        c = new SimpleSuicide();
        vm.deal(address(c), amount);
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        c.sudicideAnyone();
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + amount);
    }
}
